UPDATE questions SET choice_a = '重要度に応じてアラートの優先度を設定し、重要な警告を見逃さないようにする', choice_b = '表示するアラート数を一定数に固定し、超過分は履歴として後から確認する', choice_c = 'アラートを1日数回のサマリー形式に集約し、リアルタイム通知を控える', choice_d = 'アラートの発報基準を緩和し、わずかな逸脱でも医療者に知らせる', correct_answer = 'A', incorrect_explanation = 'A: 重要度に応じてアラートの優先度を設定し、重要な警告を見逃さないようにする（正解）
